import { site } from '../config/site';
import { i18nFor, languages, defaultLanguage, type Language } from './i18n';
import { pathFor, resolvePath, type RouteKey, type RouteParams } from './routes';
import { absoluteUrl } from './siteUrl';
import { personJsonLd } from './structuredData';
import { getBySlug } from './works';

/** Search engines cut descriptions at about this many characters. */
export const DESCRIPTION_MAX_LENGTH = 155;

/** Default share image (1200 × 630); generated by scripts/generate-og-image.mjs. */
export const OG_IMAGE_PATH = '/og-image.png';

/** Marks the head tags this module owns, so the browser can swap them on navigation. */
export const SEO_ATTRIBUTE = 'data-seo';

const OG_LOCALES: Record<Language, string> = { pl: 'pl_PL', en: 'en_GB' };

/** One `<meta>`, `<link>` or `<script>` element for `<head>`. */
export interface HeadTag {
  tag: 'meta' | 'link' | 'script';
  attrs: Record<string, string>;
  /** Text content (only for `<script>`). */
  text?: string;
}

export interface PageMeta {
  lang: Language;
  title: string;
  tags: HeadTag[];
}

/** Shortens `text` to `max` characters at a word boundary, ending with an ellipsis. */
export function truncate(text: string, max = DESCRIPTION_MAX_LENGTH): string {
  const clean = text.replace(/\s+/g, ' ').trim();
  if (clean.length <= max) return clean;
  const cut = clean.slice(0, max - 1);
  const lastSpace = cut.lastIndexOf(' ');
  return `${(lastSpace > 0 ? cut.slice(0, lastSpace) : cut).replace(/[\s,.;:–-]+$/, '')}…`;
}

/** Canonical URLs of one page in every language, plus `x-default` (Polish, for now). */
export function alternateLinks(key: RouteKey, params: RouteParams = {}): HeadTag[] {
  const links = languages.map((lang): HeadTag => ({
    tag: 'link',
    attrs: { rel: 'alternate', hreflang: lang, href: absoluteUrl(pathFor(key, lang, params)) },
  }));
  links.push({
    tag: 'link',
    attrs: {
      rel: 'alternate',
      hreflang: 'x-default',
      href: absoluteUrl(pathFor(key, defaultLanguage, params)),
    },
  });
  return links;
}

interface PageText {
  /** Page name, before the brand is added. */
  name: string;
  description: string;
  image?: string;
}

function pageText(key: RouteKey, lang: Language, params: RouteParams): PageText | null {
  const { t } = i18nFor(lang);
  switch (key) {
    case 'home':
      return { name: t('meta.home.title'), description: t('meta.home.description') };
    case 'portfolio':
      return { name: t('meta.portfolio.title'), description: t('meta.portfolio.description') };
    case 'contact':
      return { name: t('meta.contact.title'), description: t('meta.contact.description') };
    case 'privacy':
      return { name: t('meta.privacy.title'), description: t('meta.privacy.description') };
    case 'work': {
      const work = getBySlug(params.slug ?? '');
      if (!work) return null;
      return {
        name: work.title[lang],
        description: truncate(work.description[lang]),
        // Social networks do not show SVG, so placeholder covers fall back to the default image.
        ...(work.cover.endsWith('.svg') ? {} : { image: work.cover }),
      };
    }
  }
}

function meta(attr: 'name' | 'property', key: string, content: string): HeadTag {
  return { tag: 'meta', attrs: { [attr]: key, content } };
}

/** Meta for any path that is not a page: the 404, kept out of search results. */
function notFoundMeta(lang: Language): PageMeta {
  const { t } = i18nFor(lang);
  return {
    lang,
    title: t('meta.title', { page: t('meta.notFound.title'), brand: site.brand }),
    tags: [meta('name', 'robots', 'noindex')],
  };
}

/**
 * Everything `<head>` needs for `pathname`: title, description, canonical and `hreflang` links,
 * Open Graph / Twitter tags and, on the home and contact pages, `Person` structured data.
 * The same tags are written into prerendered HTML and swapped in the browser on navigation.
 */
export function getPageMeta(pathname: string): PageMeta {
  const route = resolvePath(pathname);
  if (!route) return notFoundMeta(defaultLanguage);

  const { lang, key, params } = route;
  const text = pageText(key, lang, params);
  if (!text) return notFoundMeta(lang);

  const { t } = i18nFor(lang);
  const title =
    key === 'home'
      ? `${text.name} | ${site.brand}`
      : t('meta.title', { page: text.name, brand: site.brand });
  const url = absoluteUrl(pathFor(key, lang, params));
  const image = absoluteUrl(text.image ?? OG_IMAGE_PATH);

  const tags: HeadTag[] = [
    meta('name', 'description', text.description),
    { tag: 'link', attrs: { rel: 'canonical', href: url } },
    ...alternateLinks(key, params),
    meta('property', 'og:type', 'website'),
    meta('property', 'og:site_name', site.brand),
    meta('property', 'og:title', title),
    meta('property', 'og:description', text.description),
    meta('property', 'og:url', url),
    meta('property', 'og:image', image),
    meta('property', 'og:image:alt', t('meta.ogImageAlt')),
    meta('property', 'og:locale', OG_LOCALES[lang]),
    ...languages
      .filter((other) => other !== lang)
      .map((other) => meta('property', 'og:locale:alternate', OG_LOCALES[other])),
    meta('name', 'twitter:card', 'summary_large_image'),
  ];

  if (key === 'home' || key === 'contact') {
    tags.push({
      tag: 'script',
      attrs: { type: 'application/ld+json' },
      text: JSON.stringify(personJsonLd(lang)),
    });
  }

  return { lang, title, tags };
}

function escapeHtml(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('"', '&quot;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

/** `<` inside JSON-LD would let a value close the `<script>`; `<` is the same in JSON. */
function escapeScriptText(value: string): string {
  return value.replaceAll('<', '\\u003c');
}

/** Serialises head tags for prerendered HTML, each marked with {@link SEO_ATTRIBUTE}. */
export function renderHeadTags(tags: readonly HeadTag[]): string {
  return tags
    .map(({ tag, attrs, text }) => {
      const attributes = Object.entries({ ...attrs, [SEO_ATTRIBUTE]: '' })
        .map(([name, value]) => (value === '' ? name : `${name}="${escapeHtml(value)}"`))
        .join(' ');
      return tag === 'script'
        ? `<script ${attributes}>${escapeScriptText(text ?? '')}</script>`
        : `<${tag} ${attributes}>`;
    })
    .join('\n    ');
}
